import { notFound } from 'next/navigation';
import { getContent, visibleSorted } from '@/lib/cms/db';
import JsonLd from '@/components/JsonLd';
import ProjectDetail, { type ProjectDetailData } from '@/components/projects/ProjectDetail';
import { pageMetadata, siteUrl, SITE } from '@/lib/seo';
import type { SiteContent } from '@/lib/types';

interface RouteProps {
  params: Promise<{ slug: string }>;
}

function findProject(content: SiteContent | null, slug: string): ProjectDetailData | null {
  const items = visibleSorted<ProjectDetailData>(content?.projects?.items || content?.programs?.items || []);
  return items.find((p) => p?.slug === slug) || null;
}

// Static export: enumerate every project slug at build time. Falls back
// to a placeholder when the backend is unreachable during build so Next
// can still produce a buildable route (the page handler 404s anyway).
export async function generateStaticParams() {
  const content = await getContent();
  const items = visibleSorted<ProjectDetailData>(
    content?.projects?.items || content?.programs?.items || [],
  );
  const params = items
    .filter((p) => Boolean(p?.slug))
    .map((p) => ({ slug: p.slug as string }));
  if (params.length === 0) return [{ slug: '__placeholder__' }];
  return params;
}

export async function generateMetadata({ params }: RouteProps) {
  const { slug } = await params;
  const content = await getContent();
  const project = findProject(content, slug);
  if (!project) return {};
  return pageMetadata({
    title: `${project.title} — Third Eye Worldwide`,
    description: project.desc,
    path: `/projects/${slug}`,
    type: 'article',
  });
}

export default async function ProjectDetailPage({ params }: RouteProps) {
  const { slug } = await params;
  const content = await getContent();
  const project = findProject(content, slug);
  if (!project) notFound();

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'CreativeWork',
    name: project.title,
    description: project.desc,
    url: siteUrl(`/projects/${slug}`),
    creator: { '@type': 'NGO', name: SITE.name, url: SITE.baseUrl },
    isPartOf: {
      '@type': 'CollectionPage',
      name: 'Projects',
      url: siteUrl('/projects'),
    },
  };

  return (
    <>
      <JsonLd data={jsonLd} />
      <ProjectDetail project={project} />
    </>
  );
}

1	import Link from 'next/link';
2	import CmsIcon from '@/components/CmsIcon';
3	import { ArrowRight } from '@/components/icons';
4	
5	/*
6	 * Card that renders a single project in the /projects grid.
7	 *
8	 * CMS shape: { id, slug, icon, title, desc, tag, status, visible, order }.
9	 * When `slug` is present, the entire card becomes a link to
10	 * /projects/<slug>. Legacy items without a slug render as a plain div.
11	 */
12	export interface Project {
13	  id?: string;
14	  slug?: string;
15	  icon?: string;
16	  title?: string;
17	  desc?: string;
18	  tag?: string;
19	  status?: string;
20	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
21	  [key: string]: any;
22	}
23	export default function ProjectCard({ project }: { project?: Project }) {
24	  const { icon, title, desc, tag, slug, status } = project || {};
25	  const statusClass = status ? ` prog-card-${status}` : '';
26	
27	  const inner = (
28	    <>
29	      <div className="prog-icon">
30	        <CmsIcon name={icon || 'star'} aria-hidden="true" />
31	      </div>
32	      <div className="prog-content">
33	        <h3>{title || ''}</h3>
34	        <p>{desc || ''}</p>
35	        {tag ? <span className="prog-tag">{tag}</span> : null}
36	        {slug ? (
37	          <span className="prog-learn-more" aria-hidden="true">
38	            Learn more <ArrowRight size="1em" aria-hidden="true" />
39	          </span>
40	        ) : null}
41	      </div>
42	    </>
43	  );
44	
45	  if (slug) {
46	    return (
47	      <Link
48	        href={`/projects/${slug}`}
49	        className={`prog-card prog-card-link${statusClass}`}
50	        aria-label={`${title} — learn more`}
51	      >
52	        {inner}
53	      </Link>
54	    );
55	  }
56	
57	  return <div className={`prog-card${statusClass}`}>{inner}</div>;
58	}
