1	/*
2	 * Sight Beyond Sight — design tokens (TEWW_REDESIGN_SPEC.md §2).
3	 * Night-first: the default theme is a deep indigo night lit by saffron gold.
4	 * Variable NAMES are a stable contract shared with /ad-min — only values
5	 * change here.
6	 */
7	@font-face { font-family: 'Literata'; src: url('/fonts/Literata-Variable.ttf') format('truetype-variations'); font-weight: 200 900; font-display: swap; }
8	@font-face { font-family: 'Literata'; src: url('/fonts/Literata-Italic-Variable.ttf') format('truetype-variations'); font-weight: 200 900; font-style: italic; font-display: swap; }
9	@font-face { font-family: 'Manrope'; src: url('/fonts/Manrope-Variable.ttf') format('truetype-variations'); font-weight: 200 800; font-display: swap; }
10	
11	/*
12	 * Fallback @font-face declarations with size-adjust + ascent/descent
13	 * overrides. The browser uses these while the real font files are
14	 * downloading, so the layout doesn't shift when the swap happens
15	 * (eliminates ~0.05–0.1 of CLS per page on slow networks).
16	 */
17	@font-face {
18	  font-family: 'Literata Fallback';
19	  src: local('Georgia');
20	  size-adjust: 103%;
21	  ascent-override: 95%;
22	  descent-override: 26%;
23	  line-gap-override: 0%;
24	}
25	@font-face {
26	  font-family: 'Manrope Fallback';
27	  src: local('Arial');
28	  size-adjust: 101%;
29	  ascent-override: 97%;
30	  descent-override: 24%;
31	  line-gap-override: 0%;
32	}
33	
34	/* Tailwind utilities (shadcn/ui). Preflight is disabled in tailwind.config.js
35	   so the existing reset below remains the source of truth. */
36	@tailwind base;
37	@tailwind components;
38	@tailwind utilities;
39	
40	/* ── RESET & TOKENS ─────────────────────────────── */
41	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
42	:root {
43	  --font-display: 'Literata', 'Literata Fallback', Georgia, serif;
44	  --font-body: 'Manrope', 'Manrope Fallback', sans-serif;
45	  --font-mono: 'DM Mono', 'Courier New', monospace;
46	  --radius-sm: 6px; --radius-md: 10px; --radius-lg: 16px; --radius-xl: 24px; --radius-full: 9999px;
47	  --space-1:.25rem;--space-2:.5rem;--space-3:.75rem;--space-4:1rem;--space-6:1.5rem;--space-8:2rem;--space-10:2.5rem;--space-12:3rem;--space-16:4rem;--space-20:5rem;--space-24:6rem;
48	  --maxw: 1280px;
49	
50	  /* Fluid display scale — headlines carry the editorial voice. */
51	  --text-hero: clamp(2.75rem, 1.9rem + 3.6vw, 5rem);
52	  --text-title: clamp(2rem, 1.55rem + 1.9vw, 3.25rem);
53	  --text-subtitle: clamp(1.35rem, 1.15rem + .8vw, 1.75rem);
54	
55	  /* Header height — used by the topnav and every sticky element that
56	     sits below it (subnav on /media /about /documents, the story-detail
57	     reading-progress bar, etc). Keeping it as a variable means future
58	     nav height changes don't need to hunt down hard-coded 68 px values
59	     across the stylesheet. */
60	  --header-height: 68px;
61	
62	  /*
63	   * CMS UI redesign — density + sidebar width vars (cms-redesign-plan.md §1).
64	   * Defaults match comfortable density. Overridden inside the CMS shell via
65	   * the `[data-density]` attribute on .adm-shell.
66	   */
67	  --row-y:    10px;
