/* ── Legacy .prog-card link styles ─────────────────────────────
   /projects no longer uses ProjectCard, but the HOME page still
   renders it (base .prog-card styles live in 02-base-sections.css).
   Kept here, tokenized, so home cards stay styled; delete once the
   home redesign stops consuming ProjectCard. */
.prog-card-link {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 18px;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  transition: transform .2s, border-color .2s, box-shadow .2s;
}
.prog-card-link:hover {
  transform: translateY(-2px);
  border-color: var(--border-strong);
  box-shadow: var(--shadow-md);
}
.prog-card-link:hover .prog-learn-more { color: var(--brand); gap: 10px; }
.prog-card-link .prog-tag { margin-top: 12px; }
.prog-learn-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: .82rem;
  font-weight: 700;
  color: var(--fg-muted);
  transition: color .2s, gap .2s;
}
.prog-card-coming-soon { position: relative; border-style: dashed; }
.prog-card-coming-soon::before {
  content: 'Coming soon';
  position: absolute;
  top: 14px;
  right: 14px;
  font-size: .66rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--bg-subtle);
  border: 1px solid var(--border);
  padding: 4px 10px;
  border-radius: var(--radius-full);
}
